// The Stratalk section's playground (stratalk/, generated by
// doc/manual/gen/genstratalk.py): StrataOS (build/bootrom.stx and disk.img)
// in the WebAssembly emulator, with the REPL started at the shell's first
// prompt (stratalk -j). It shares the play page's machinery: the worker
// (../play/worker.js), the module (../play/strata-emu.wasm) and the images
// come from ../play/. This file only moves bytes: console output to the
// terminal, keys, the editor's text and "Try" examples to the worker. What
// is sent before the REPL is up waits until its prompt shows.
"use strict";
(function () {
  // tools/web-stamp.sh puts the build id here; every asset URL carries it
  const BUILD = "__BUILD__";
  const V = "?v=" + BUILD;
  const PLAY = "../play/";
  const params = new URLSearchParams(location.search);
  // The JIT as on the play page (../play/jit.js): on but on iPhones, with a
  // budget on iPhone and iPad (worker.js reads it), off after it cost this
  // browser the page; ?jit=0 / ?jit=1 decide.
  const JIT_LIMITS = StrataJIT.LIMITS;
  const jitStart = StrataJIT.choose(params);
  let jitOn = jitStart.on;
  const args = () => [jitOn ? "-J" : "-j", "-c", "8", "-d", "disk.img", "bootrom.stx"];

  const $ = (id) => document.getElementById(id);
  const pg = $("pg"), toggle = $("pg-toggle"), statusEl = $("pg-status");
  const enc = new TextEncoder();
  const wide = () => matchMedia("(min-width: 1280px)").matches;
  const touch = () => matchMedia("(pointer: coarse)").matches;

  // -------------------------------------------------------------- terminal
  const term = new Terminal({
    convertEol: true, cursorBlink: true, scrollback: 5000,
    fontFamily: '"JetBrains Mono", ui-monospace, Menlo, monospace', fontSize: 13,
    theme: {
      background: "#05080f", foreground: "#cfe8ff", cursor: "#ffb347", cursorAccent: "#05080f",
      selectionBackground: "rgba(77, 225, 255, 0.3)",
      black: "#0b1120", red: "#ff6b6b", green: "#5be3a1", yellow: "#ffb347", blue: "#4d8dff",
      magenta: "#c38bff", cyan: "#4de1ff", white: "#cfe8ff",
      brightBlack: "#5b7088", brightRed: "#ff8f8f", brightGreen: "#8af0bf", brightYellow: "#ffd08a",
      brightBlue: "#7fb0ff", brightMagenta: "#dab4ff", brightCyan: "#9bf0ff", brightWhite: "#ffffff",
    },
  });
  const fit = new FitAddon.FitAddon();
  term.loadAddon(fit);
  term.open($("pg-term"));
  function refit() {
    if (!$("pg-term").offsetHeight) return; // the drawer is closed
    try { fit.fit(); } catch (e) { /* not laid out yet */ }
    term.scrollToBottom();
  }
  document.fonts.load('13px "JetBrains Mono"').then(() => document.fonts.ready).then(() => {
    const f = term.options.fontFamily;
    term.options.fontFamily = "monospace";
    term.options.fontFamily = f;
    refit();
  });
  new ResizeObserver(refit).observe($("pg-term"));
  term.writeln("\x1b[36mStratalk\x1b[0m under StrataOS in the WebAssembly emulator: type, or press Try on an example.");

  // -------------------------------------------------------------- the machine
  let W = null, stopped = true, pending = "", booted = false, gen = 0;
  let last = { t: 0, steps: 0 };

  let wasmModule = null;
  async function compileWasm() {
    if (wasmModule) return wasmModule;
    try {
      wasmModule = await WebAssembly.compileStreaming(fetch(PLAY + "strata-emu.wasm" + V));
    } catch (e) { // a server without application/wasm
      wasmModule = await WebAssembly.compile(await (await fetch(PLAY + "strata-emu.wasm" + V)).arrayBuffer());
    }
    return wasmModule;
  }
  let images = null;
  function fetchImages() {
    const get = (n) => fetch(PLAY + "images/" + n + V).then((r) => {
      if (!r.ok) throw new Error("images/" + n + ": " + r.status);
      return r.arrayBuffer();
    });
    if (!images) images = Promise.all([get("bootrom.stx"), get("disk.img")]);
    return images;
  }
  // the console until the REPL is up: the shell's prompt starts it, its
  // prompt lets what waits go
  const dec = new TextDecoder();
  let seen = "", phase = 0;            // 0 booting, 1 the REPL starting, 2 the REPL is up
  function watch(data) {
    if (phase === 2) return;
    seen = (seen + (typeof data === "string" ? data : dec.decode(data))).slice(-200);
    if (phase === 0 && seen.includes("strata$ ")) { phase = 1; seen = ""; post("stratalk -j\n"); }
    else if (phase === 1 && seen.includes("st> ")) { phase = 2; if (pending) { post(pending); pending = ""; } }
  }

  function setStatus(s, isStop) {
    statusEl.textContent = s;
    statusEl.classList.toggle("stopped", !!isStop);
    if (isStop) StrataJIT.disarm();
  }

  function post(s) {
    let bytes = [];
    for (const ch of s) for (const b of enc.encode(ch === "\r" ? "\n" : ch)) bytes.push(b);
    if (bytes.length) W.postMessage({ t: "input", data: new Uint8Array(bytes) });
  }
  // Bytes for the console; before the machine is up they wait here.
  function send(s) {
    if (W && !stopped && phase === 2) post(s);
    else { pending += s; boot(); }
  }

  function onWorker(w, m) {
    if (w !== W) return;
    switch (m.t) {
    case "out": watch(m.data); term.write(m.data, () => term.scrollToBottom()); break;
    case "started":
      last = { t: performance.now(), steps: 0 };
      setStatus("running · StrataOS, 8 cores");
      break;
    case "status": {
      const t = performance.now();
      const mips = (m.steps - last.steps) / ((t - last.t) * 1000);
      last = { t, steps: m.steps };
      setStatus(`running · ${m.live}/${m.cores} cores live · ` +
                (mips >= 1 ? `${mips.toFixed(0)} MIPS (${m.jit ? "JIT" : "interpreter"})` : "waiting for input") +
                ` · ${(m.steps / 1e6).toFixed(1)}M instructions`);
      break;
    }
    case "stopped":
      stopped = true;
      setStatus((m.state === 1 ? (m.faulted ? "halted: a core faulted" : "every core halted")
                 : m.state === 2 ? "deadlock" : "stopped") + " · Reset to boot again", true);
      break;
    case "exit": stopped = true; setStatus(`exited (${m.code}) · Reset`, true); break;
    case "error": stopped = true; setStatus("error: " + m.msg, true); break;
    }
  }

  async function boot() {
    if (booted) return;
    booted = true;
    const my = ++gen;
    setStatus("loading…");
    term.write("\x1bc");
    term.write(`\x1b[2m$ strata-emu ${args().join(" ")}\x1b[0m\n`);
    try {
      const [wasm, imgs] = await Promise.all([compileWasm(), fetchImages()]);
      if (my !== gen) return;               // Reset meanwhile
      const w = new Worker(PLAY + "worker.js" + V);
      W = w;
      stopped = false;
      w.onmessage = (e) => onWorker(w, e.data);
      w.onerror = (e) => { if (w === W) { stopped = true; setStatus("error: " + (e.message || "the worker failed"), true); } };
      if (jitOn) StrataJIT.arm();           // until it has run a while (jit.js)
      phase = 0; seen = "";
      w.postMessage(Object.assign({ t: "start", wasm, files: [{ name: "bootrom.stx", data: imgs[0].slice(0) },
                                                             { name: "disk.img", data: imgs[1].slice(0) }],
                                    args: args() }, JIT_LIMITS));
    } catch (e) {
      booted = false;
      setStatus("error: " + (e && e.message ? e.message : e), true);
    }
  }

  function reset() {
    if (W) W.terminate();
    W = null;
    StrataJIT.disarm();
    stopped = true;
    booted = false;
    pending = "";
    boot();
  }

  // -------------------------------------------------------------- the drawer
  function isOpen() { return wide() || pg.classList.contains("open"); }
  function setOpen(on) {
    pg.classList.toggle("open", on);
    toggle.setAttribute("aria-expanded", String(on || wide()));
    toggle.querySelector(".pg-title").textContent = (on || wide() ? "▾" : "▸") + " PLAYGROUND";
    if (on || wide()) { requestAnimationFrame(refit); boot(); }
  }
  toggle.addEventListener("click", () => { if (!wide()) setOpen(!pg.classList.contains("open")); });
  addEventListener("resize", () => setOpen(pg.classList.contains("open")));
  for (const b of document.querySelectorAll("[data-pg-open]"))
    b.addEventListener("click", () => { setOpen(true); term.focus(); });
  setOpen(false);                            // wide: open, and boots now

  // -------------------------------------------------------------- input
  term.onData((d) => { term.scrollToBottom(); send(d); });
  $("pg-reset").addEventListener("click", () => { reset(); if (!touch()) term.focus(); });
  // the JIT off after it cost this browser the page (jit.js): say so, and
  // offer it back
  if (jitStart.note) {
    $("pg-jitnote-t").textContent = jitStart.note;
    $("pg-jitnote").hidden = false;
    $("pg-jit-on").addEventListener("click", () => {
      StrataJIT.forget();
      jitOn = true;
      $("pg-jitnote").hidden = true;
      reset();
    });
  }

  // -------------------------------------------------------------- the editor
  // A textarea over a <pre> that site/hl.js colours: both sit in one grid
  // cell with the same font and padding, the textarea's text is transparent
  // (its caret and selection are not), and the box around them scrolls both
  // together. The text is kept per browser (localStorage).
  const src = $("pg-src"), hlEl = $("pg-ed-hl");
  const KEY = "strata-stratalk-editor";
  const SAMPLE = "\"Edit, then Run (Ctrl+Enter): classes, methods and statements, filed in.\"\n" +
    "Object subclass: #Counter slots: 'n'.\n" +
    "Counter >> increment [ n := (n ifNil: [0]) + 1. ^n ]\n" +
    "Counter >> n [ ^n ]\n" +
    "| c | c := Counter new. 5 timesRepeat: [c increment]. c n\n";
  const norm = (s) => s.replace(/\r\n?/g, "\n");
  let hlQueued = false, saveTimer = 0;
  function highlight() {
    hlQueued = false;
    const html = window.StrataHL ? StrataHL.stLines(src.value.split("\n")).join("\n")
      : src.value.replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" })[c]);
    hlEl.innerHTML = html + "\n ";   // room for an empty last line
    fitSource();
  }
  // the textarea covers the <pre> exactly (the box around them scrolls)
  const pre = hlEl.parentElement;
  function fitSource() {
    const r = pre.getBoundingClientRect();
    src.style.width = r.width + "px";
    src.style.height = r.height + "px";
  }
  new ResizeObserver(fitSource).observe($("pg-ed"));
  function changed() {
    if (!hlQueued) { hlQueued = true; requestAnimationFrame(highlight); }
    clearTimeout(saveTimer);
    saveTimer = setTimeout(() => { try { localStorage.setItem(KEY, src.value); } catch (e) { /* no storage */ } }, 300);
  }
  // Replaces the text; where the browser can, as an edit (Ctrl+Z brings the old text back)
  function load(text) {
    text = norm(text);
    let done = false;
    if (!touch() && document.queryCommandSupported && document.queryCommandSupported("insertText")) {
      const had = document.activeElement;
      src.focus({ preventScroll: true });
      src.select();
      try { done = document.execCommand("insertText", false, text); } catch (e) { done = false; }
      if (had && had !== src && had.focus) had.focus({ preventScroll: true });
    }
    if (!done || src.value !== text) src.value = text;
    src.setSelectionRange(0, 0);
    src.scrollTop = 0;
    $("pg-ed").scrollTop = 0;
    $("pg-ed").scrollLeft = 0;
    changed();
  }
  try { const t = localStorage.getItem(KEY); src.value = t === null ? SAMPLE : t; } catch (e) { src.value = SAMPLE; }
  highlight();
  src.addEventListener("input", changed);

  // Run: a single line is evaluated and printed; more is filed in as one
  // line (Compiler fileIn: '...'), so what it defines stays in the session
  function run(text) {
    text = norm(text).trim();
    if (!text) return;
    if (!isOpen()) setOpen(true);
    if (text.includes("\n")) text = "Compiler fileIn: '" + text.replace(/'/g, "''").replace(/\n/g, " ") + "'";
    send(text + "\n");
    term.scrollToBottom();
  }
  // the selection, whole lines; without one, the line with the cursor
  function selectedLines() {
    const v = src.value;
    let a = src.selectionStart, b = src.selectionEnd;
    if (b > a && v[b - 1] === "\n") b--;
    a = v.lastIndexOf("\n", a - 1) + 1;
    const e = v.indexOf("\n", b);
    return v.slice(a, e < 0 ? v.length : e);
  }
  $("pg-run").addEventListener("click", () => run(src.value));
  $("pg-runsel").addEventListener("click", () => run(selectedLines().split("\n")[0]));
  $("pg-rerun").addEventListener("click", () => { reset(); run(src.value); });
  const mac = /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent);
  $("pg-key").textContent = (mac ? "⌘" : "Ctrl+") + "Enter";
  let tabFree = false;    // after Esc, Tab leaves the editor instead of indenting
  src.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) {
      e.preventDefault();
      run(src.value);
    } else if (e.key === "Escape") {
      tabFree = true;
    } else if (e.key === "Tab" && !tabFree && !e.shiftKey && !e.altKey && !e.ctrlKey && !e.metaKey) {
      e.preventDefault();
      const col = src.selectionStart - (src.value.lastIndexOf("\n", src.selectionStart - 1) + 1);
      const pad = " ".repeat(2 - (col % 2));
      if (!document.execCommand || !document.execCommand("insertText", false, pad))
        src.setRangeText(pad, src.selectionStart, src.selectionEnd, "end");
      changed();
    } else if (e.key !== "Tab" && e.key !== "Shift") {
      tabFree = false;
    }
  });
  src.addEventListener("blur", () => { tabFree = false; });

  // Try: an example goes into the editor and runs
  document.addEventListener("click", (e) => {
    const b = e.target.closest(".try-b");
    if (!b) return;
    if (!isOpen()) setOpen(true);
    load(b.dataset.try + "\n");
    run(src.value);
    b.classList.add("sent");
    setTimeout(() => b.classList.remove("sent"), 600);
    if (!touch()) term.focus({ preventScroll: true });
  });

  // the examples (lang/stratalk/examples/*.st, on the disk under
  // /stratalk/examples): filed in from there
  const demos = $("pg-demos");
  for (const name of (window.STRATALK_EXAMPLES || [])) {
    const o = document.createElement("option");
    o.value = name;
    o.textContent = name + ".st";
    demos.appendChild(o);
  }
  demos.addEventListener("change", () => {
    const name = demos.value;
    demos.value = "";
    if (!name) return;
    if (!isOpen()) setOpen(true);
    send("(File named: '/stratalk/examples/" + name + ".st') fileIn\n");
    if (!touch()) term.focus({ preventScroll: true });
  });
})();
